import { BlockList, isIP } from "node:net";
import { lookup } from "node:dns/promises";
import { rootLogger } from "../shared/logger";

const logger = rootLogger.child("deploy-hook");

const MAX_ATTEMPTS = 3;
const RETRY_DELAY_MS = 250;
const REQUEST_TIMEOUT_MS = 5_000;

export interface DeployHookResult {
  readonly ok: boolean;
  readonly attempts: number;
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

class UnsafeDeployHookUrlError extends Error {}

// Ranges an author-supplied deployHookUrl must never resolve to: loopback,
// the RFC 1918 / ULA private ranges, link-local (which is also where the
// AWS/GCP/Azure cloud-metadata endpoint lives), and multicast. Node's
// BlockList matches an IPv4-mapped IPv6 address against an "ipv4" subnet
// when checked as "ipv6", so one list covers both families.
const RESERVED_ADDRESSES = new BlockList();
RESERVED_ADDRESSES.addSubnet("0.0.0.0", 8, "ipv4");
RESERVED_ADDRESSES.addSubnet("10.0.0.0", 8, "ipv4");
RESERVED_ADDRESSES.addSubnet("127.0.0.0", 8, "ipv4");
RESERVED_ADDRESSES.addSubnet("169.254.0.0", 16, "ipv4");
RESERVED_ADDRESSES.addSubnet("172.16.0.0", 12, "ipv4");
RESERVED_ADDRESSES.addSubnet("192.168.0.0", 16, "ipv4");
RESERVED_ADDRESSES.addSubnet("224.0.0.0", 4, "ipv4");
RESERVED_ADDRESSES.addSubnet("::1", 128, "ipv6");
RESERVED_ADDRESSES.addSubnet("fc00::", 7, "ipv6");
RESERVED_ADDRESSES.addSubnet("fe80::", 10, "ipv6");

function isReservedAddress(address: string): boolean {
  const version = isIP(address);
  if (version === 4) return RESERVED_ADDRESSES.check(address, "ipv4");
  if (version === 6) return RESERVED_ADDRESSES.check(address, "ipv6");
  return true;
}

/**
 * A site's deployHookUrl is plain text an author fills in themselves, so it
 * has to be treated the same as any other user-controlled fetch target: an
 * allowlist of hosts isn't possible (it's meant to point at whatever static
 * host the customer happens to use), so this validates the *resolved*
 * address instead of the URL string, on every attempt — a rejected first
 * lookup shouldn't be bypassable by a DNS record that changes before the
 * retry (DNS rebinding).
 */
async function assertSafeDeployHookUrl(rawUrl: string): Promise<URL> {
  let url: URL;
  try {
    url = new URL(rawUrl);
  } catch {
    throw new UnsafeDeployHookUrlError(`"${rawUrl}" is not a valid URL.`);
  }

  if (url.protocol !== "https:" && url.protocol !== "http:") {
    throw new UnsafeDeployHookUrlError(`"${url.protocol}" is not an allowed protocol.`);
  }

  const hostname = url.hostname.toLowerCase();
  if (hostname === "localhost" || hostname.endsWith(".internal")) {
    throw new UnsafeDeployHookUrlError(`"${hostname}" is not a publicly routable host.`);
  }

  const addresses = isIP(hostname)
    ? [hostname]
    : (await lookup(hostname, { all: true })).map((entry) => entry.address);

  if (addresses.length === 0 || addresses.some(isReservedAddress)) {
    throw new UnsafeDeployHookUrlError(`"${hostname}" does not resolve to a public address.`);
  }

  return url;
}

/**
 * Calls a site's deploy hook after a publish. Most static-hosting deploy
 * hooks are a bare POST with no body, and most are flaky enough on a cold
 * start to be worth one retry — this gives it two.
 *
 * A failed hook does not fail the publish: the post and its revision are
 * already committed by the time this runs (see routes in app.ts), so the
 * worst case is a site that doesn't rebuild on its own. The caller surfaces
 * `ok: false` to the editor rather than losing the failure silently.
 */
export async function triggerDeployHook(siteSlug: string, url: string): Promise<DeployHookResult> {
  let lastError: unknown;

  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt += 1) {
    try {
      logger.debug({ siteSlug, attempt }, "Started calling the deploy hook.");
      const safeUrl = await assertSafeDeployHookUrl(url);
      const response = await fetch(safeUrl, {
        method: "POST",
        redirect: "manual",
        signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
      });
      if (!response.ok) {
        throw new Error(`Deploy hook responded with status ${response.status}.`);
      }
      logger.info({ siteSlug, attempt }, "Completed calling the deploy hook.");
      return { ok: true, attempts: attempt };
    } catch (error) {
      lastError = error;
      const reason = error instanceof Error ? error.message : String(error);
      if (error instanceof UnsafeDeployHookUrlError) {
        logger.error({ siteSlug, attempt, reason }, "Deploy hook URL failed safety validation.");
        return { ok: false, attempts: attempt };
      }
      logger.warn({ siteSlug, attempt, reason }, "Deploy hook call failed; retrying.");
      if (attempt < MAX_ATTEMPTS) await sleep(RETRY_DELAY_MS * attempt);
    }
  }

  const reason = lastError instanceof Error ? lastError.message : String(lastError);
  logger.error(
    { siteSlug, attempts: MAX_ATTEMPTS, reason },
    "Deploy hook failed after every retry.",
  );
  return { ok: false, attempts: MAX_ATTEMPTS };
}
